CREATE OR REPLACE FUNCTION public.gather_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare tx int; ty int; here int; t tile_def;
begin
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  here := land_tile(p_world, tx, ty);
  select * into t from tile_def where id = here;

  if p_action = 'cut_down' then
    -- It may have come down since this was asked for; do not swing at air.
    if here not in (tile_id('Tree'), tile_id('Bush')) then return 'No tree or bush here.'; end if;
  elsif p_action = 'forage' then
    if not t.forage then return 'Nothing grows here worth looking through.'; end if;
    if is_foraged(p_world, tx, ty, 'forage') then return 'Already searched. ' || ready_in(p_world, tx, ty, 'forage'); end if;
  elsif p_action = 'botanize' then
    if not t.botanize then return 'Nothing grows here worth looking through.'; end if;
    if is_foraged(p_world, tx, ty, 'botanize') then return 'Already searched. ' || ready_in(p_world, tx, ty, 'botanize'); end if;
  elsif p_action = 'collect' then
    if not t.collect then return 'Nothing to collect here.'; end if;
  end if;
  return null;
end $function$
